    if (m.has(ph.id)) continue; const sz = ph.layout === 'page' || ph.layout === 'land' ? Math.round(max * 2) : ph.layout === 'full' ? Math.round(max * 1.5) : max;
    let im = null;
    if (p && ph.src && ph.edit && ph.edit.pins) { try { const c = await renderPhoto(p, ph, sz); im = { url: c.toDataURL('image/jpeg', 0.88), w: c.width, h: c.height }; } catch (e) { console.warn(e); } } // the points as they are now
    m.set(ph.id, im || await Photos.dataURL(ph, sz));
