    const pins = pagePins(p, d.id, pg); if (!pins.length) continue; const zs = pageZones(d, pg);
    if (!zs.length) { out.push({ d, r, pg, pins }); continue; }
    // 0.9.19: one plan per snapshot (LG1, LG2 …) with its points; points outside every snapshot on the whole page
    const src = Docs.source(r, pg); const by = new Map(zs.map(z => [z.id, []])); const rest = [];
